     if r1+r2<=r:s.update(a*b for a in a1 for b in a2)
     if r1==min(r,n1) and r2==min(r,n2):s.update(a*2**n2+b*2**n1-2*a*b for a in a1 for b in a2)
  W[n,r]=s
